package com.heathen.persephone;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.location.Location;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Map camera and markers share one projection. Foreground-only exploration never auto-starts. */
@android.annotation.SuppressLint("SetTextI18n")
public final class KoreGoActivity extends Activity implements RadioScanner.Sink {
    private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();
    private PinGate gate;private PingStore pings;private RadioScanner scanner;private SessionStore store;private SessionStore.Session session;private TileCache tiles;private SignalMapView map;
    private TextView status,coordinates;private Button explore;private boolean live,visible,demoMode;private int epoch;private Location gps;
    private String selected="";private final ArrayDeque<SignalMapModel.Point> history=new ArrayDeque<>();
    private final Runnable tick=new Runnable(){public void run(){if(!visible)return;if(live&&!gate.unlocked()){stop();status.setText("Unlock expired // exploration saved");}if(gps!=null&&SystemClock.elapsedRealtime()-gps.getElapsedRealtimeNanos()/1000000>10000){gps=null;map.receiver(null);}refresh();ui.postDelayed(this,1000);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE|WindowManager.LayoutParams.FLAG_FULLSCREEN);
        gate=new PinGate(this);pings=PingStore.get(this);scanner=new RadioScanner(this,this);store=new SessionStore(this);tiles=new TileCache(this);
        FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xff050d14);map=new SignalMapView(this,tiles,key->{selected=key;refresh();choosePing(key);});map.gameStyle(true);root.addView(map,new FrameLayout.LayoutParams(-1,-1));
        LinearLayout legend=column();legend.setPadding(dp(10),dp(8),dp(10),dp(8));legend.setBackgroundColor(0xdf07131c);legend.addView(label("KOREGO // FIELD MAP",17,0xffffde43));
        android.text.SpannableString keys=new android.text.SpannableString("● Flock  ● Raven  ● Falcon/LPR\n● Wi-Fi  ● BLE  ● Camera");int[] colors={0xff41f4e7,0xffde69ff,0xffffde43,0xff749fba,0xff79a6ff,0xffffaa66};int at=0;for(int color:colors){int next=keys.toString().indexOf('●',at);keys.setSpan(new android.text.style.ForegroundColorSpan(color),next,next+1,0);at=next+1;}TextView key=label("",10,0xffd4e5ec);key.setText(keys);legend.addView(key);legend.addView(label("RECEPTION SIGHTINGS // UNVERIFIED",9,0xffafc4ce));
        status=label("Unlock, then Explore. Map / Dex available locally.",11,0xffd4e5ec);status.setMaxLines(3);legend.addView(status);
        LinearLayout tools=new LinearLayout(this);for(String title:new String[]{"+","−","Follow","Tiles","Demo"})tools.addView(button(title,()->{if(title.equals("+"))map.zoom(1);else if(title.equals("−"))map.zoom(-1);else if(title.equals("Follow"))map.center();else if(title.equals("Tiles"))approveTiles();else unlock(this::startDemo);}),new LinearLayout.LayoutParams(0,dp(34),1));legend.addView(tools);
        FrameLayout.LayoutParams top=new FrameLayout.LayoutParams(dp(265),-2,Gravity.TOP|Gravity.START);top.topMargin=dp(24);top.leftMargin=dp(10);root.addView(legend,top);
        LinearLayout bottom=column();bottom.setPadding(dp(8),dp(6),dp(8),dp(6));bottom.setBackgroundColor(0xdf07131c);coordinates=label("GPS not acquired // map points are reception history",11,0xff41f4e7);coordinates.setMaxLines(3);bottom.addView(coordinates);
        LinearLayout actions=new LinearLayout(this);explore=button("Explore",()->{if(live)stop();else unlock(this::approveExplore);});actions.addView(explore,new LinearLayout.LayoutParams(0,dp(46),1));actions.addView(button("Signal Dex",()->unlock(()->startActivity(new Intent(this,SignalDexActivity.class)))),new LinearLayout.LayoutParams(0,dp(46),1));actions.addView(button("Desk",()->startActivity(new Intent(this,MainActivity.class).putExtra("settings",true))),new LinearLayout.LayoutParams(0,dp(46),1));bottom.addView(actions);
        FrameLayout.LayoutParams foot=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);root.addView(bottom,foot);root.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);refresh();
    }
    @Override protected void onStart(){super.onStart();visible=true;ui.post(tick);}
    @Override protected void onStop(){visible=false;epoch++;ui.removeCallbacks(tick);stop();tiles.online(false);gps=null;map.receiver(null);super.onStop();}
    @Override protected void onDestroy(){tiles.close();io.shutdown();super.onDestroy();}
    private void unlock(Runnable action){if(gate.unlocked()){action.run();return;}EditText input=new EditText(this);input.setHint(gate.isDefault()?"Initial passcode: 9818":"Passcode");input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);final int visit=epoch;AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Unlock KoreGo for one hour").setView(input).setPositiveButton("Unlock",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String pin=input.getText().toString();dialog.getButton(-1).setEnabled(false);io.execute(()->{try{boolean ok=gate.verify(pin);ui.post(()->{if(!visible||visit!=epoch){dialog.dismiss();return;}dialog.getButton(-1).setEnabled(true);if(ok){dialog.dismiss();action.run();}else input.setError(gate.remainingMs()>0?"Cooldown: wait one minute":"Incorrect passcode");});}catch(Exception error){ui.post(()->{dialog.dismiss();status.setText("Unlock failed: "+error.getMessage());});}});}));dialog.show();}
    private void approveExplore(){List<String> needed=new ArrayList<>(Arrays.asList(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION));if(Build.VERSION.SDK_INT>=31){needed.add(Manifest.permission.BLUETOOTH_SCAN);needed.add(Manifest.permission.BLUETOOTH_CONNECT);}needed.removeIf(p->checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED);if(!needed.isEmpty()){requestPermissions(needed.toArray(new String[0]),50);return;}
        LinearLayout box=column();box.setPadding(dp(18),dp(8),dp(18),dp(8));CheckBox wifi=new CheckBox(this);wifi.setText("Standard Wi-Fi scans every 30 seconds");wifi.setTextColor(Color.WHITE);wifi.setEnabled(!gate.isDefault());wifi.setChecked(!gate.isDefault());box.addView(wifi);box.addView(label("Explore records local Wi-Fi/BLE reception and phone GPS. Standard scans may transmit ordinary probes. Approve only within your authorized training setting. No network association or packet injection. Set a personal PIN in Desk to enable periodic Wi-Fi. Android may throttle requests.",14,0xffafc4ce));final int visit=epoch;
        new AlertDialog.Builder(this).setTitle("Approve this exploration session").setView(box).setPositiveButton("Explore",(d,w)->{if(!visible||visit!=epoch||!gate.unlocked())return;if(OverlayService.active()){status.setText("Stop external overlay before integrated exploration");return;}io.execute(()->{try{store.audit(wifi.isChecked()?"korego_wifi_refresh_30s":"korego_listening_explore","local scan area","Operator approved exploration in authorized training setting");ui.post(()->{if(visible&&visit==epoch&&gate.unlocked())start(wifi.isChecked());});}catch(Exception error){ui.post(()->status.setText("Approval audit failed; exploration blocked"));}});}).setNegativeButton("Cancel",null).show();
    }
    @Override public void onRequestPermissionsResult(int request,String[] names,int[] grants){super.onRequestPermissionsResult(request,names,grants);status.setText("Permissions updated // tap Explore to approve a session");}
    private void start(boolean refresh){if(live||!gate.unlocked())return;try{demoMode=false;session=store.new Session(false);live=true;scanner.start();if(refresh)scanner.automaticWifi(true);explore.setText("Stop / Save");getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);status.setText("Exploring // "+(refresh?"Wi-Fi requests every 30s":"platform Wi-Fi listener")+" + BLE");}catch(Exception error){stop();status.setText("Explore failed: "+error.getMessage());}}
    private void stop(){scanner.stop();if(!live)return;live=false;explore.setText("Explore");getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);SessionStore.Session completed=session;session=null;String destination=getSharedPreferences("settings",0).getString("tree","");io.execute(()->{try{completed.close();pings.flush();if(!destination.isEmpty())store.export(completed.file,android.net.Uri.parse(destination));}catch(Exception error){android.util.Log.e("KoreGo","Private session retained after export failure",error);}});status.setText("Exploration paused // private session saved");}
    @Override public void observation(JSONObject row){if(!live||!gate.unlocked())return;try{DetectionAnnotator.annotate(row);pings.observe(row);DexLedger.record(this,row);SignalMapModel.Point point=DetectionAnnotator.point(row);if(point!=null){history.addLast(point);while(history.size()>2000)history.removeFirst();}SessionStore.Session recording=session;io.execute(()->{try{recording.append(row);}catch(Exception error){ui.post(()->{if(session==recording){stop();status.setText("Recording stopped // private source retained");}});}});}catch(Exception error){status.setText("Observation rejected");}}
    @Override public void status(String message){if(status!=null)status.setText(message);}
    @Override public void location(Location value){long age=SystemClock.elapsedRealtime()-value.getElapsedRealtimeNanos()/1000000;if(!OverlayProjection.validGeo(value.getLatitude(),value.getLongitude())||value.isFromMockProvider()||age<0||age>10000||!value.hasAccuracy()||value.getAccuracy()<=0||value.getAccuracy()>100)return;gps=new Location(value);map.receiver(gps);}
    private void refresh(){if(map==null)return;if(!gate.unlocked()){gps=null;map.receiver(null);map.setData(Collections.emptyList(),"");coordinates.setText("LOCKED // unlock for reception history and exploration");return;}List<SignalMapModel.Point> points=new ArrayList<>();for(JSONObject ping:pings.list()){if(ping.optString("source").equals("DEMO")!=demoMode)continue;SignalMapModel.Point point=PingStore.point(ping);if(point!=null)points.add(point);}points.sort(Comparator.comparingLong(p->p.time));map.setData(points,selected);
        String text=demoMode?"DEMO // synthetic reception positions // no radios":gps==null?"GPS unresolved // north-up map // reception history":String.format(Locale.ROOT,"YOU %.5f %.5f ±%.0f m%s",gps.getLatitude(),gps.getLongitude(),gps.getAccuracy(),gps.hasBearing()&&gps.hasSpeed()&&gps.getSpeed()>=1?String.format(Locale.ROOT," // course %.0f°",gps.getBearing()):"");for(SignalMapModel.Point point:points)if(point.key.equals(selected)){text+="\n"+direction(gps,point);break;}coordinates.setText(text);
    }
    static String direction(Location gps,SignalMapModel.Point point){if(gps==null||gps.isFromMockProvider()||SystemClock.elapsedRealtime()-gps.getElapsedRealtimeNanos()/1000000<0||SystemClock.elapsedRealtime()-gps.getElapsedRealtimeNanos()/1000000>10000||!point.valid())return "Bearing unresolved // RSSI is not a direction measurement";float[] result=new float[3];Location.distanceBetween(gps.getLatitude(),gps.getLongitude(),point.lat,point.lon,result);if(!gps.hasAccuracy()||result[0]<=3*(gps.getAccuracy()+point.accuracy))return "Recorded reception is within GPS uncertainty";return String.format(Locale.ROOT,"TO RECORDED RECEPTION: %.0f m / %.0f° true north",result[0],(result[1]+360)%360);}
    private void startDemo(){stop();demoMode=true;gps=null;map.receiver(null);selected="";try{String[] names={"Flock demo","Raven demo","Falcon demo","Reolink camera demo","Workshop BLE demo"};for(int i=0;i<names.length;i++){JSONObject row=new JSONObject().put("source","DEMO").put("radio",i==1||i==4?"BLE":"Wi-Fi").put("address",String.format(Locale.ROOT,"02:00:00:DE:00:%02X",i)).put("name",names[i]).put("time",java.time.Instant.now().toString()).put("rssi",-45-i*8).put("latitude",36.1146+(i-2)*.00018).put("longitude",-115.1728+Math.sin(i)*.00035).put("accuracy",5).put("connectable",false);DetectionAnnotator.annotate(row);pings.observe(row);DexLedger.record(this,row);}status.setText("DEMO // original creatures / synthetic sightings / no RF");refresh();map.center();}catch(Exception error){status.setText("Demo unavailable: "+error.getMessage());}}
    private void choosePing(String key){List<String> neighbors=map.nearbyKeys(key);if(neighbors.size()>1){List<JSONObject> options=new ArrayList<>();for(JSONObject ping:pings.list())if(neighbors.contains(ping.optString("key")))options.add(ping);String[] names=new String[options.size()];for(int i=0;i<names.length;i++){JSONObject ping=options.get(i);names[i]=DexCatalog.title(this,DexCatalog.kind(ping))+" / "+ping.optInt("rssi")+" dBm / "+ping.optString("name");}new AlertDialog.Builder(this).setTitle("Sightings near this reception point").setItems(names,(d,index)->{selected=options.get(index).optString("key");refresh();chooseIndividualPing(selected);}).setNegativeButton("Cancel",null).show();return;}chooseIndividualPing(key);}
    private void chooseIndividualPing(String key){for(JSONObject ping:pings.list())if(ping.optString("key").equals(key)){String id=ping.optString("id");new AlertDialog.Builder(this).setTitle(DexCatalog.title(this,DexCatalog.kind(ping))).setMessage(ping.optString("name")+"\n"+ping.optString("tags")+" // "+ping.optString("confidence")+" candidate\n"+ping.optString("evidence")+"\nRSSI "+ping.optInt("rssi")+" dBm; position is a reception/phone note.").setPositiveButton("GPS / photos / nickname",(d,w)->unlock(()->startActivity(new Intent(this,PingEditorActivity.class).putExtra("ping_id",id)))).setNegativeButton("Close",null).show();break;}}
    private void approveTiles(){if(tiles.isOnline()){tiles.online(false);map.invalidate();return;}unlock(()->new AlertDialog.Builder(this).setTitle("Street basemap / OpenStreetMap").setMessage("OSM receives your IP and this visible map area. Names, addresses, creatures, and observations remain local. Only visible tiles are loaded; no bulk download. Tiles turn off when this page leaves the foreground.").setPositiveButton("Enable",(d,w)->{if(gate.unlocked()&&visible){tiles.online(true);map.invalidate();}}).setNegativeButton("Cancel",null).show());}
    private LinearLayout column(){LinearLayout view=new LinearLayout(this);view.setOrientation(LinearLayout.VERTICAL);return view;}
    private TextView label(String value,int size,int color){TextView view=new TextView(this);view.setText(value);view.setTextSize(size);view.setTextColor(color);view.setTypeface(Typeface.MONOSPACE);return view;}
    private Button button(String title,Runnable action){Button view=new Button(this);view.setText(title);view.setOnClickListener(v->action.run());HudBackground.style(view);return view;}
    private int dp(int value){return (int)(value*getResources().getDisplayMetrics().density+.5f);}
}
